-- 0006_question_bank_300.sql
-- Bar Exam question bank: 300 multiple-choice questions
-- (100 easy, 100 medium, 100 hard), compiled 8-9 Oct 2026 with sources.
--
-- * Retires every older question (kept, not deleted, because past rounds
--   point at them) and shows only active questions to the app.
-- * Adds a stable code (E001, M042, X100...) so questions can be edited
--   later by re-running this file or a smaller one.
-- * Adds round_answer_counts so the app can move on as soon as everyone
--   in a pool has answered.
--
-- Safe to re-run: questions are upserted by code.

alter table questions add column if not exists code text;
alter table questions add column if not exists active boolean not null default true;
alter table questions add column if not exists source text;
create unique index if not exists questions_code_key on questions (code);

-- Retire everything that isn't part of this bank.
update questions set active = false where code is null;

create or replace view questions_public as
  select id, prompt, choices, category, difficulty, image_url, created_at
  from questions
  where active;

grant select on questions_public to anon, authenticated;

-- How many players have answered each round (no names, no answers).
create or replace view round_answer_counts as
  select round_id, count(*)::int as answered
  from answers
  group by round_id;

grant select on round_answer_counts to anon, authenticated;

on conflict (code) do update set
  prompt = excluded.prompt,
  choices = excluded.choices,
  correct_choice = excluded.correct_choice,
  category = excluded.category,
  difficulty = excluded.difficulty,
  source = excluded.source,
  active = true;
